import React, { useEffect, useState } from "react";
import axios from "axios";

const GroupesList = () => {
    const [groupes, setGroupes] = useState([]);
    const [tuteurs, setTuteurs] = useState([]);
    const [sujets, setSujets] = useState([]);
    const [etudiants, setEtudiants] = useState([]);

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            const [groupesResponse, tuteursResponse, sujetsResponse, etudiantsResponse] = await Promise.all([
                axios.get("http://localhost:3001/api/groupes"),
                axios.get("http://localhost:3001/api/tuteurs"),
                axios.get("http://localhost:3001/api/sujets"),
                axios.get("http://localhost:3001/api/etudiants"),
            ]);

            console.log("Groupes:", groupesResponse.data);
            console.log("Tuteurs:", tuteursResponse.data);
            console.log("Sujets:", sujetsResponse.data);
            console.log("Étudiants:", etudiantsResponse.data);

            setGroupes(groupesResponse.data);
            setTuteurs(tuteursResponse.data);
            setSujets(sujetsResponse.data);
            setEtudiants(etudiantsResponse.data);
        } catch (error) {
            console.error("Erreur lors de la récupération des données:", error);
        }
    };

    return (
        <div>
            <h2>Liste des groupes</h2>
            <ul>
                {groupes.map((groupe) => {
                    const tuteur = tuteurs.find(t => t.idTuteur == groupe.idTuteur);
                    const sujet = sujets.find(s => s.idSujet == groupe.idSujet);
                    const groupeEtudiants = etudiants.filter(e => e.idGroupe == groupe.idGroupe);
                    
                    console.log(`Groupe ${groupe.nomGroupe}: Tuteur -`, tuteur, ", Sujet -", sujet);
                    
                    return (
                        <li key={groupe.idGroupe}>
                            <strong>{groupe.nomGroupe}</strong>
                            <p>Tuteur: {tuteur ? tuteur.nomTuteur : "Non affecté"}</p>
                            <p>Sujet: {sujet ? sujet.nomSujet : "Non affecté"}</p>
                            <p>Étudiants: {groupeEtudiants.map(e => e.nomEtudiant).join(", ") || "Aucun"}</p>
                        </li>
                    );
                })}
            </ul>
        </div>
    );
};

export default GroupesList;
